#include <bits/stdc++.h>
using namespace std;using U=uint64_t;int n;U adj[64];
bool cycle(int s,int v,U used,int rem){if(!rem)return (adj[v]>>s)&1;U a=adj[v]&~used&(~U(0)<<(s+1));while(a){int w=__builtin_ctzll(a);a&=a-1;if(cycle(s,w,used|(U(1)<<w),rem-1))return true;}return false;}
bool powerfree(){for(int p=4;p<=n;p*=2)for(int s=0;s+p<=n;s++)if(cycle(s,s,U(1)<<s,p-1))return false;return true;}
void lengths(int v,int t,U used,int d,U&sp){if(v==t){sp|=U(1)<<d;return;}U a=adj[v]&~used;while(a){int w=__builtin_ctzll(a);a&=a-1;lengths(w,t,used|(U(1)<<w),d+1,sp);}}
int main(){string g;long long total=0,survive=0,tests=0,hits=0;while(cin>>g){if(g.empty()||g[0]=='>')continue;n=g[0]-63;if(n<4||n>14||g.size()!=1+(n*(n-1)/2+5)/6)return 2;fill(adj,adj+64,0);int k=0;for(int j=1;j<n;j++)for(int i=0;i<j;i++,k++)if(((g[1+k/6]-63)>>(5-k%6))&1){adj[i]|=U(1)<<j;adj[j]|=U(1)<<i;}total++;if(!powerfree())continue;survive++;vector<int> deg(n);for(int i=0;i<n;i++)deg[i]=__builtin_popcountll(adj[i]);U cache[64][64]{};bool done[64][64]{};auto spec=[&](int a,int b){if(!done[a][b]){U s=0;lengths(a,b,U(1)<<a,0,s);cache[a][b]=cache[b][a]=s;done[a][b]=done[b][a]=true;}return cache[a][b];};for(int a=0;a<n;a++)for(int b=0;b<n;b++)if(b!=a)for(int c=0;c<n;c++)if(c!=a&&c!=b){int defects=0;for(int i=0;i<n;i++)defects+=deg[i]+(i==a||i==b||i==c)<3;if(defects>1)continue;U x=spec(a,b),y=spec(a,c),z=spec(b,c);tests++;bool ok15=(x&~U(32760))==0&&(y&~U(32760))==0&&(z&~U(32736))==0;bool ok7s=n<7&&(x&~U(124))==0&&(y&~U(124))==0&&(z&~U(124))==0;bool ok7a=n<7&&(x&~U(124))==0&&(y&~U(124))==0&&(z&~U(120))==0;if(ok15||ok7s||ok7a){hits++;cout<<"{\"g6\":"<<quoted(g)<<",\"n\":"<<n<<",\"ports\":["<<a<<","<<b<<","<<c<<"],\"spectra\":["<<x<<","<<y<<","<<z<<"],\"old15\":"<<ok15<<",\"old7s\":"<<ok7s<<",\"old7a\":"<<ok7a<<"}\n";}}}cerr<<"{\"enumerated\":"<<total<<",\"powerfree\":"<<survive<<",\"port_tests\":"<<tests<<",\"hits\":"<<hits<<"}\n";}
